window.docContents[157].resolve({"/Lexer-and-grammar/Rules-of-the-chapter/#Core-C______--Lexer-and-grammar--Rules-of-the-chapter":{"contents":"Every rule of inference of this chapter, in the order of its sections. Each rule is stated with its explanation, and with the definition of its notation, in the section named above it. The lexer and the grammar are given by an automaton and by productions, not by rules of inference.\n\nPreprocessor\n\n\n\n\n\n\n\n\n\n\n","context":"Core C++\u0009Lexer and grammar","header":"1.5. Rules of the chapter","id":"/Lexer-and-grammar/Rules-of-the-chapter/#Core-C______--Lexer-and-grammar--Rules-of-the-chapter"}});